create function public.is_required_wrap_day(d date) returns boolean
language plpgsql stable security definer set search_path='' as $$
begin
 if d is null or d<date '2020-01-01' or d>date '2040-12-31' then raise exception 'Challenge calendar needs an update'; end if;
 return extract(dow from d)<>6 and not exists(select 1 from public.wrap_calendar_exemptions e where e.day=d);
end $$;
revoke all on function public.is_required_wrap_day(date) from public,anon;
grant execute on function public.is_required_wrap_day(date) to authenticated,service_role;
create function public.wrap_comment_words(value text) returns integer
language sql immutable set search_path='' as $$
 select count(*)::integer from regexp_matches(coalesce(value,''),U&'[^[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]+','g');
$$;
revoke all on function public.wrap_comment_words(text) from public,anon;
grant execute on function public.wrap_comment_words(text) to authenticated,service_role;
-- Existing posts are preserved; the new caption rule applies to future submissions.
create or replace function public.submit_checkin(photo_path text, photo_caption text default '', is_shared boolean default true)
returns uuid language plpgsql security definer set search_path='' as $$
declare member_id uuid := auth.uid(); local_day date; result_id uuid; member_tz text;
begin
  if member_id is null then raise exception 'Sign in before posting a wrap.'; end if;
  select p.timezone into member_tz from public.profiles p where p.id=member_id;
  if member_tz is null then raise exception 'Your profile is not ready.'; end if;
  local_day := (now() at time zone member_tz)::date;
  if not public.is_required_wrap_day(local_day) then raise exception 'No wrap required on Shabbat or Yom Tov.'; end if;
  if public.wrap_comment_words(photo_caption)>10 then raise exception 'Comments must be 10 words or fewer.'; end if;
  if split_part(photo_path,'/',1) <> member_id::text then raise exception 'Invalid photo owner.'; end if;
  if not exists(select 1 from storage.objects o where o.bucket_id='checkins' and o.name=photo_path and o.created_at >= now()-interval '1 hour') then raise exception 'Upload a new photo first.'; end if;
  insert into public.checkins(user_id,checkin_date,photo_path,caption,shared)
  values(member_id,local_day,photo_path,coalesce(photo_caption,''),is_shared) returning id into result_id;
  return result_id;
end;
$$;
create or replace function public.settle_net_month(target_month date,mode boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare net bigint; weight numeric; fees bigint; forfeited bigint; required integer;
begin
 if extract(day from target_month)<>1 then raise exception 'First day required'; end if;
 perform pg_advisory_xact_lock(hashtext('levav-settle:'||mode),hashtext(target_month::text));
 if exists(select 1 from public.settlements where month=target_month and livemode=mode) then return '{"status":"already_settled"}'; end if;
 perform 1 from public.enrollments where month=target_month and livemode=mode for update;
 if not found then raise exception 'No paid enrollments'; end if;
 if exists(select 1 from public.enrollments where month=target_month and livemode=mode and (now() at time zone timezone)::date<(target_month+interval '1 month')::date) then raise exception 'Month still active'; end if;
 if exists(select 1 from public.enrollments e left join public.billing_invoices i on i.id=e.payment_reference where e.month=target_month and e.livemode=mode and (i.id is null or i.status<>'paid' or i.available_at>now())) then raise exception 'Payments await reconciliation'; end if;
 if exists(select 1 from public.checkins c join public.enrollments e on e.user_id=c.user_id where e.month=target_month and e.livemode=mode and c.checkin_date>=target_month and c.checkin_date<target_month+interval '1 month' and public.is_required_wrap_day(c.checkin_date) and c.review_status='pending') then raise exception 'Photo review pending'; end if;
 select count(*) into required from generate_series(target_month::timestamp,target_month+interval '1 month'-interval '1 day',interval '1 day') d where public.is_required_wrap_day(d::date);
 create temporary table net_work on commit drop as select e.user_id,e.contribution_cents,
 (select count(*) from public.checkins c where c.user_id=e.user_id and c.checkin_date>=target_month and c.checkin_date<target_month+interval '1 month' and public.is_required_wrap_day(c.checkin_date) and c.review_status='approved')=required as completed
 from public.enrollments e where e.month=target_month and e.livemode=mode;
 select sum(contribution_cents) filter(where completed),coalesce(sum(contribution_cents) filter(where not completed),0) into weight,forfeited from net_work;
 if coalesce(weight,0)=0 then raise exception 'No finishers: rollover decision required'; end if;
 select sum(i.fee_cents) into fees from public.billing_invoices i join public.enrollments e on e.payment_reference=i.id where e.month=target_month and e.livemode=mode;
 select sum(contribution_cents)-fees into net from net_work;
 if net<=0 then raise exception 'No net funds'; end if;
 with raw as(select user_id,floor(net*contribution_cents::numeric/weight)::bigint as base,mod(net*contribution_cents::numeric,weight) as remainder from net_work where completed),
 ranked as(select *,row_number() over(order by remainder desc,user_id) as rank,net-sum(base) over() as leftover from raw)
 insert into public.ledger(user_id,amount_cents,description,external_id,livemode)
 select user_id,base+case when rank<=leftover then 1 else 0 end,'Monthly pool after processing fees','net-settlement:'||mode||':'||target_month||':'||user_id,mode from ranked where base+case when rank<=leftover then 1 else 0 end>0;
 insert into public.settlements(month,forfeited_cents,livemode) values(target_month,forfeited,mode);
 update public.enrollments set settled_at=now() where month=target_month and livemode=mode;
 drop table net_work;
 return jsonb_build_object('status','settled','fees_cents',fees,'distributed_cents',net);
end $$;
